"<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><title>Astro Remote</title>"
"<style>*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#090d13;color:#edf4ff;font-family:Arial,sans-serif}body{background:radial-gradient(circle at 50% 0,#142238 0,#090d13 42%,#06080c 100%)}header{height:64px;display:flex;align-items:center;gap:12px;padding:0 18px;border-bottom:1px solid #263447;background:rgba(9,13,19,.94)}header a{color:#c8d6e8;text-decoration:none;font-weight:800}.brand{font-weight:900;letter-spacing:.09em}.spacer{flex:1}.pill{padding:6px 9px;border:1px solid #34465f;border-radius:999px;color:#9eb1c8;font-size:12px}.pill.on{color:#9ee7bb;border-color:#315841}.pill.bad{color:#ffb6bf;border-color:#61323b}main{padding:22px;max-width:1180px;margin:0 auto}.grid{display:grid;grid-template-columns:minmax(0,1fr) 410px;gap:16px}.screen{background:#020304;border:1px solid #28394f;border-radius:16px;overflow:hidden;box-shadow:0 28px 90px rgba(0,0,0,.38);min-height:520px;display:grid;place-items:center}.screen-inner{text-align:center;padding:30px;max-width:650px}.screen h2{margin:0 0 10px;font-size:30px}.screen p{margin:0;color:#7f93aa;line-height:1.55}.pin{font-size:54px;font-weight:900;letter-spacing:.15em;margin:24px 0 10px}.account{font-family:monospace;font-size:16px;color:#b9c9dc;word-break:break-all}.badge{display:inline-block;margin:18px 0 4px;padding:8px 12px;border-radius:999px;border:1px solid #5b3d22;color:#ffd29a;background:#24190f;font-size:12px;font-weight:800}.badge.ok{border-color:#315841;color:#a7e9ba;background:#10251d}.panel{border:1px solid #29394e;background:#0f1620;border-radius:16px;padding:18px;height:max-content}.panel h3{margin:0 0 16px}.row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #202c3b;font-size:13px}.row span:first-child{color:#8397af}.row span:last-child{text-align:right;font-weight:700;word-break:break-all}.note{margin-top:14px;color:#71859d;font-size:12px;line-height:1.5}.error{margin-top:12px;color:#ff9da9;font-size:12px;display:none}button{width:100%;margin-top:10px;padding:11px;border-radius:9px;border:1px solid #405676;background:#162235;color:#eaf2ff;font-weight:800;cursor:pointer}.primary{background:#d8e7f8;color:#091019;border-color:#d8e7f8}.activate{background:#10251d;border-color:#315841;color:#a7e9ba}.danger{background:#261519;border-color:#61323b;color:#ffb6bf}.secondary{background:#151c26;color:#c9d8e9;border-color:#34465f}button:disabled{opacity:.45}@media(max-width:820px){.grid{grid-template-columns:1fr}main{padding:12px}.pin{font-size:38px}.screen{min-height:360px}}</style></head><body>"
"<header><a href='/'>← Astro</a><span class='brand'>REMOTE SERVICE</span><span id='servicePill' class='pill'>WORKER</span><span class='spacer'></span><span id='phasePill' class='pill'>IDLE</span></header>"
"<main><div class='grid'><section class='screen'><div class='screen-inner'><h2 id='screenTitle'>Preparando Astro Remote</h2><p id='screenText'>O Astro valida a conta ativa antes do pareamento.</p><div id='badge' class='badge'>LENDO CONTA</div><div id='pin' class='pin'>--------</div><div id='account' class='account'></div><p id='timer'></p></div></section>"
"<aside class='panel'><h3>Conta ativa</h3><div class='row'><span>Leitura</span><span id='accRc'>...</span></div><div class='row'><span>Nome</span><span id='accName'>...</span></div><div class='row'><span>UID</span><span id='accUid'>...</span></div><div class='row'><span>Slot</span><span id='accSlot'>...</span></div><div class='row'><span>Account ID</span><span id='accId'>...</span></div><div class='row'><span>Tipo</span><span id='accType'>...</span></div><div class='row'><span>Flags</span><span id='accFlags'>...</span></div><div class='row'><span>Status</span><span id='accStatus'>...</span></div><div class='row'><span>Novo Account ID</span><span id='accProposed'>...</span></div><button id='activate' class='activate' disabled>FAKE ATIVAR ESTA CONTA</button><button id='refresh' class='secondary'>RELER USUÁRIO ATIVO</button>"
"<h3 style='margin-top:20px'>Remote Play</h3><div class='row'><span>Worker</span><span id='worker'>...</span></div><div class='row'><span>Uso remoto</span><span id='rpEnabled'>...</span></div><div class='row'><span>Servidor 9295</span><span id='rpPort'>...</span></div><div class='row'><span>Pareamento</span><span id='pairing'>...</span></div><div class='row'><span>Erro RP</span><span id='pairErr'>-</span></div><button id='pair' class='primary' disabled>GERAR PIN OFFLINE</button><button id='cancel' class='danger'>CANCELAR PAREAMENTO</button><button id='restart' class='secondary'>REINICIAR SERVIÇO INTERNO</button><div id='error' class='error'></div><div class='note'>Fluxo: detectar conta → confirmar usuário → fake ativar → reiniciar o PS5 → gerar PIN → parear → remoto. O Astro só ativa o usuário que estiver em primeiro plano.</div></aside></div></main>"
"<script>const $=id=>document.getElementById(id);let busy=false,acc=null;function lock(v){busy=v;['pair','cancel','refresh','restart','activate'].forEach(x=>$(x).disabled=v||($(x).dataset.blocked==='1'))}function err(t){$('error').textContent=t||'';$('error').style.display=t?'block':'none'}function pinfmt(n){n=String(Number(n)||0).padStart(8,'0');return n.slice(0,4)+' '+n.slice(4)}function hex(n){n=Number(n)||0;return n?'0x'+(n>>>0).toString(16).toUpperCase():'-'}async function fetchJson(url,ms=1800,opt={}){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{cache:'no-store',signal:c.signal,...opt});const j=await r.json();if(!r.ok)throw new Error((j.error||'HTTP '+r.status)+(j.rc!==undefined?' rc='+j.rc:''));return j}finally{clearTimeout(t)}}function renderAccount(a){acc=a;const ok=a.account_rc===0,activated=!!a.account_activated;$('accRc').textContent=ok?'OK':'rc='+String(a.account_rc);$('accName').textContent=a.account_name||'-';$('accUid').textContent=ok?String(a.account_user):'-';$('accSlot').textContent=ok?String(a.account_slot):'-';$('accId').textContent=a.account_id_hex||'-';$('accType').textContent=a.account_type||'(offline)';$('accFlags').textContent=String(a.account_flags||0);$('accStatus').textContent=activated?'FAKE ATIVADA':'OFFLINE NÃO ATIVADA';$('accProposed').textContent=a.account_proposed_id_hex||'-';$('activate').dataset.blocked=(!ok||activated)?'1':'0';$('activate').disabled=busy||!ok||activated;$('pair').dataset.blocked=(!ok||!activated||a.reboot_required)?'1':'0';$('pair').disabled=busy||!ok||!activated||a.reboot_required;$('badge').textContent=activated?'CONTA ATIVADA':'CONTA OFFLINE NÃO ATIVADA';$('badge').className='badge '+(activated?'ok':'');if(a.reboot_required){$('screenTitle').textContent='Ativação concluída';$('screenText').textContent='Reinicie o PS5 antes de gerar o PIN.';$('badge').textContent='REINÍCIO OBRIGATÓRIO'}else if(activated){$('screenTitle').textContent='Conta pronta';$('screenText').textContent='A conta está ativada. Agora o Astro pode gerar o PIN offline.'}else if(ok){$('screenTitle').textContent='Conta offline detectada';$('screenText').textContent='Confira o usuário e confirme a fake ativação.'}}async function readAccount(){try{const a=await fetchJson('/service/remote/_root/account/status',2500);renderAccount(a)}catch(e){$('accRc').textContent='ERRO';err('Conta: '+String(e.message||e))}}async function status(){try{let j={};try{j=await fetchJson('/api/remote/status',900)}catch(e){}const w=await fetchJson('/service/remote/_root/status',900);const online=!!j.service_online,pin=!!w.pairing_pin_ready,done=!!w.pairing_complete,active=!!w.pairing_active;$('worker').textContent=j.worker_pid?('astrorem PID '+j.worker_pid):('astrorem PID '+String(w.pid||'?'));$('rpEnabled').textContent=w.remoteplay_enabled?'HABILITADO':'DESATIVADO';$('rpPort').textContent=w.remoteplay_tcp_9295?'RESPONDENDO':'SEM RESPOSTA';$('pairing').textContent=done?'CONCLUÍDO':(active?'AGUARDANDO DISPOSITIVO':'PARADO');$('pairErr').textContent=hex(w.pairing_error);$('pin').textContent=pin?pinfmt(w.pairing_pin):'--------';$('account').textContent=pin?('Account ID: '+w.pairing_account_id):'';$('timer').textContent=pin?('Tempo restante: '+String(w.pairing_seconds_left||0)+'s'):'';$('servicePill').textContent=online?'WORKER ONLINE':'WORKER';$('servicePill').className='pill '+(online?'on':'');$('phasePill').textContent=(w.phase||j.phase||'idle').replaceAll('_',' ').toUpperCase()}catch(e){err('Remote status: '+String(e.message||e))}}async function act(path){if(busy)return;lock(true);err('');try{await fetchJson(path,6000,{method:'POST'});await readAccount();await status()}catch(e){err(String(e.message||e));await readAccount();await status()}finally{lock(false)}}$('refresh').onclick=readAccount;$('activate').onclick=()=>{if(!acc||acc.account_rc!==0||acc.account_activated)return;const msg='Confirmar fake ativação desta conta?\n\nNome: '+(acc.account_name||'-')+'\nUID: '+acc.account_user+'\nSlot: '+acc.account_slot+'\nNovo Account ID: '+acc.account_proposed_id_hex+'\n\nDepois será necessário reiniciar o PS5.';if(confirm(msg))act('/service/remote/_root/account/activate')};$('pair').onclick=()=>act('/service/remote/_root/pairing/prepare');$('cancel').onclick=()=>act('/service/remote/_root/pairing/cancel');$('restart').onclick=()=>act('/api/remote/restart');readAccount();status();setInterval(()=>{if(!busy)status()},1000);</script></body></html>";

